#!/usr/bin/env node
// Drift check between actual Express routes and .agents/context/api-endpoints.md.
// The catalog's purpose ("check this file to avoid duplication") only works if
// it's COMPLETE — it was found 31% stale on 2026-07-31 (94 documented vs 136
// real handlers). Hand-written prose sections stay curated; this script keeps
// the raw inventory complete by rewriting an auto-generated section between
// markers at the bottom of the doc.
//
// Usage:
//   node .claude/scripts/check-api-endpoints.js          # report drift, exit 1 if any
//   node .claude/scripts/check-api-endpoints.js --write  # append missing to generated section
const fs = require('fs');
const path = require('path');
const ROOT = path.resolve(__dirname, '../../');
const DOC = path.join(ROOT, '.agents/context/api-endpoints.md');
const ROUTES_DIR = path.join(ROOT, 'artifacts/api-server/src/routes');

// Mount prefixes from routes/index.ts (path-prefixed mounts only; everything
// else mounts at /api directly). Heuristic — update if index.ts adds prefixes.
const PREFIX = { 'macro.ts': '/macro' };

const endpoints = []; // { method, path, file }
for (const f of fs.readdirSync(ROUTES_DIR).filter(f => f.endsWith('.ts') && f !== 'index.ts')) {
  const src = fs.readFileSync(path.join(ROUTES_DIR, f), 'utf8');
  for (const m of src.matchAll(/router\.(get|post|put|delete|patch)\(\s*["'`]([^"'`]+)["'`]/g)) {
    endpoints.push({ method: m[1].toUpperCase(), path: '/api' + (PREFIX[f] ?? '') + m[2], file: f });
  }
}

const doc = fs.readFileSync(DOC, 'utf8');
const BEGIN = '<!-- AUTOGEN:BEGIN (node .claude/scripts/check-api-endpoints.js --write) -->';
const END = '<!-- AUTOGEN:END -->';

// "Documented" must mean documented in a CURATED section — the autogen block is
// this script's own output, not documentation. Counting it made the script
// self-referential: each --write recomputed `missing` against a doc that already
// contained the block, so the block shrank to near-empty and every endpoint listed
// only there was silently dropped (136 documented -> 87 in one run, 2026-08-27).
const curated = doc.includes(BEGIN)
  ? doc.slice(0, doc.indexOf(BEGIN)) + doc.slice(doc.indexOf(END) + END.length)
  : doc;

// Param names may differ between code and doc: normalize :param segments.
const norm = p => p.replace(/:[^/]+/g, ':P').replace(/\/$/, '');
const pathsIn = text => new Set([...text.matchAll(/\|\s*(GET|POST|PUT|DELETE|PATCH)\s*\|\s*(\/api[^\s|]*)/g)]
  .map(m => m[1] + ' ' + norm(m[2])));

const curatedPaths = pathsIn(curated);
const allDocPaths  = pathsIn(doc);

// --write regenerates the block, so it must list everything absent from CURATED prose.
const missingFromCurated = endpoints.filter(e => !curatedPaths.has(e.method + ' ' + norm(e.path)));
// The drift check asks "is the catalog complete?" — the autogen block does count there.
const missing = endpoints.filter(e => !allDocPaths.has(e.method + ' ' + norm(e.path)));

if (process.argv.includes('--write')) {
  const lines = [BEGIN,
    '## Auto-listed endpoints (in code, not yet in curated sections above)',
    '> Regenerated by `node .claude/scripts/check-api-endpoints.js --write`. Move entries',
    '> up into a curated section (with Purpose) when touching them; they disappear from',
    '> here on next regen once documented above.', '',
    '| Method | Path | Route file |', '|---|---|---|',
    ...missingFromCurated.map(e => `| ${e.method} | ${e.path} | ${e.file} |`),
    END];
  let out = doc.includes(BEGIN)
    ? doc.slice(0, doc.indexOf(BEGIN)) + lines.join('\n') + doc.slice(doc.indexOf(END) + END.length)
    : doc.trimEnd() + '\n\n' + lines.join('\n') + '\n';
  fs.writeFileSync(DOC, out);
  console.log(`Wrote ${missingFromCurated.length} auto-listed endpoints to generated section.`);
} else {
  console.log(`Routes in code: ${endpoints.length} | documented: ${endpoints.length - missing.length} | missing from doc: ${missing.length}`);
  for (const e of missing) console.log(`  ${e.method} ${e.path}  (${e.file})`);
  process.exit(missing.length ? 1 : 0);
}
